{"results": [{"id": "FAM:SF-APPM-058", "label": "Study family SF-APPM-058: PNR shot-level season rates vs possession labels", "score": 1.168, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-058 (0.74)", "request matches RQC:RQC-048 (0.68); FAM:SF-APPM-058 auto_addresses_question RQC:RQC-048"], "attributes": {"observed_research_question": "PNR shot-level season rates vs possession labels", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "PBP-derived shot-level PNR rates sit in a realistic band (script notes possession-level rates will be higher) and vary by team as expected.", "observed_result": "2024-25 shot-level PNR share of half-court shots ranges from OKC 7.567% (498/6581) and BOS 7.854% to IND 13.824% (856/6192) and NYK 11.959%. ATL 11.361%, DEN 11.404%, PHX 10.232% (bh 7.050 / roll 3.181).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No pass/fail gate in the output; rates are a calibration input for PBPProxyPNR (later logs show calibrated PNR ~17.9-19.6% of possessions).", "observed_sample_and_power": "30 teams, half_court_shots ~5994-6581", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": []}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 1.155, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-022 (0.73)", "request matches RQC:RQC-040 (0.67); FAM:SF-APPM-022 auto_addresses_question RQC:RQC-040"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result": "Q5c verdict 'rank-1 suppressor varies meaningfully across players'; e.g. Jokic after opp POST_UP 1.1271 (-0.0675, SE +/-0.0500, n=480); Curry forced POST_UP -0.209.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in doc.", "observed_sample_and_power": "SE per cell reported", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Initiator possessions for 4 then ~30 stars (gate >=15); Q5c ranks opponent prior-PT by target PPP for 14 players; reruns 2026-05-06 and 2026-05-30."}, "relationships": []}, {"id": "FAM:SF27", "label": "Study family SF27: Linear team+opponent+play_type baseline vs simulation kernel", "score": 0.805, "reached_via": ["request matches RQC:RQC-070 (0.69); FAM:SF27 auto_addresses_question RQC:RQC-070", "FAM:SF-PAP-098 auto_related_family (record_link_related_to) FAM:SF27"], "attributes": {"observed_research_question": "Linear team+opponent+play_type baseline vs simulation kernel", "auto_outcome_status": "inconclusive", "observed_hypothesis": "The Monte Carlo simulation kernel predicts margins better than a linear PPP~team+opponent+play_type model.", "observed_result": ["[CHT-004] SPOT_UP PPP 2.83 to 1.16 (fixed); linear margin R = +0.505; kernel Det. R = +0.466 (gap 0.001 vs linear additive R = +0.467); 5/5 perturbation tests.", "[PAP-097] linear Margin R=+0.505, win accuracy 64-68%; deterministic kernel R=+0.466 vs linear +0.467 (gap 0.001) after the multiplicative rewrite; earlier additive kernel compressed variance"], "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": ["[CHT-004] NOT_RECORDED", "[PAP-097] kernel R=+0.466 matches linear +0.467; does not beat the simple model"], "observed_sample_and_power": "[CHT-004] NOT_RECORDED"}, "relationships": []}, {"id": "FAM:SF-APPS-058", "label": "Study family SF-APPS-058: Observed on-ball defensive scheme labels (ORL-DET G1)", "score": 0.77, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-058 (0.77)"], "attributes": {"observed_research_question": "Observed on-ball defensive scheme labels (ORL-DET G1)", "auto_outcome_status": "untestable", "observed_hypothesis": "NBA matchup/PBP fields can label on-ball coverage (DROP/ICE/SWITCH) at usable rates.", "observed_result": "DET: 67 on-ball HC poss, 10 labeled (14.9%) ? DROP n=5 PPP=1.20, ICE_CANDIDATE n=5 PPP=0.80, OTHER n=57 PPP=1.42. ORL: 60 poss, 2 labeled (3.3%). switches_on unpopulated.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Confident label rates 14.9% and 3.3%; NBA matchups feed did not populate switches_on.", "observed_sample_and_power": "n=67/60 possessions, 10/2 labeled", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "failed_gate"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-PAP-098", "label": "Study family SF-PAP-098: Calibrated simulation vs Elo/net-rating/lineup+/- baselines", "score": 0.738, "reached_via": ["request matches the question or hypothesis of FAM:SF-PAP-098 (0.74)"], "attributes": {"observed_research_question": "Calibrated simulation vs Elo/net-rating/lineup+/- baselines", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "The calibrated simulation beats simple team-level baselines on PPP MAE, win accuracy, log loss, and calibration error.", "observed_result": "VAL: CALIBRATION PPP MAE 0.1152 win 68.9% vs Elo 0.1154 / 69.4% and avg PPP 0.0928 / 67.9%; HOLDOUT: CALIBRATION PPP MAE 0.3369 win 54.8% logloss 0.778 vs Elo 0.3319 / 58.1% / 0.658 and lineup+/- win 64.5%", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "holdout win accuracy 54.8% vs lineup+/- 64.5% and Elo 58.1%; val-to-holdout collapse 68.9%->54.8%", "observed_sample_and_power": "val ~193 games; holdout 155 games", "auto_validation_status": "same_pipeline_validation; evidence: PAP-098: 'validation ~193 games mid-jan-feb; holdout 155 games late-feb through'"}, "relationships": []}, {"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 0.683, "reached_via": ["FAM:SF-APPS-058 auto_related_family (limitation_precedent) FAM:SF-APPA-001", "request matches RQC:RQC-002 (0.69); FAM:SF-APPA-001 auto_addresses_question RQC:RQC-002"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF13", "label": "Study family SF13: Within-game did_adapt toward SHOULD counters improves PPP", "score": 0.516, "reached_via": ["request matches RQC:RQC-002 (0.69); FAM:SF13 auto_addresses_question RQC:RQC-002", "request matches VAR:three_point_attempts_or_luck (0.69); FAM:SF13 auto_measures VAR:three_point_attempts_or_luck"], "attributes": {"observed_research_question": "Within-game did_adapt toward SHOULD counters improves PPP", "auto_outcome_status": "artifact", "observed_hypothesis": "Offenses that shift toward the counter play types for the inferred opponent scheme gain PPP later in the game.", "observed_result": ["[APPA-003] 531 rows with inferred scheme; 249 adapted (46.9%); adapters +0.0701 (n=239) vs non-adapters +0.0121 (n=269), advantage +0.0580 PPP; DROP +0.1001, SWITCH -0.0436, HELP +0.0450.", "[APPM-013] Adapter dPPP +0.0613 vs +0.0131; advantage +0.0482 PPP, p=0.0199. SWITCH subgroup reversed (-0.0160).", "[CHT-018] First run: adapters n=229 mean dPPP +0.0613 vs non-adapters; later 586 rows, 90.6% inferable, adapters +0.0701 vs non-adapters +0.0121, lift +0.058 (n=508). T1: no-signal baseline is highest dPPP so +0.05 lift  [cut; read_family for the full text]"]}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.444, "reached_via": ["request matches RQC:RQC-055 (0.70); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-055"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF-APPA-067", "label": "Study family SF-APPA-067: TOV_FORCE 3-ply adversarial surviving lift", "score": 0.442, "reached_via": ["request matches RQC:RQC-032 (0.70); FAM:SF-APPA-067 auto_addresses_question RQC:RQC-032"], "attributes": {"observed_research_question": "TOV_FORCE 3-ply adversarial surviving lift", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Raw R1 TOV-force channel lifts survive opponent re-route or PT-shift (R2) and our follow-the-ball counter (R3).", "observed_result": "R1 lifts shrink ~50%+: ORL Banchero/Huerter +8.4 to net +3.7pp; DET Green/Anthony +7.0 to +3.5; PHI Harris/Vucevic +12.0 to +6.0; BOS Holiday/Council +6.1 to +2.8; PHX Booker/Wiggins +14.8 to +7.5; OKC Dort/Coffey +12.0  [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Net lift is model-implied, not observed in the games; R3 often additive surrogate at n<10.", "observed_sample_and_power": "4 games; 8 offense-defense sides", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-010"}, {"rel": "auto_measures", "node": "VAR:turnovers"}]}, {"id": "FAM:SF-APPS-012", "label": "Study family SF-APPS-012: Defensive PPP allowed and possession share, RS vs playoffs", "score": 0.433, "reached_via": ["request matches RQC:RQC-049 (0.69); FAM:SF-APPS-012 auto_addresses_question RQC:RQC-049"], "attributes": {"observed_research_question": "Defensive PPP allowed and possession share, RS vs playoffs", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Playoff defenses suppress DRIVE more than RS defenses (both lower PPP allowed and lower share).", "observed_result": "DRIVE allowed 1.191 -> 0.923 (-0.268), share 21.2% -> 18.2%; PNR -0.139, share +12.1pp; PULL_UP +0.341, share -7.6pp.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test; PNR share jump of +12.1pp may reflect tagging differences.", "observed_sample_and_power": "25 teams", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "25 defensive teams, min 30 poss per cell; RS vs playoff PPP allowed and opponent possession share by PT.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}], "n_results": 10}

